        body+=f'<p><a class="button secondary" href="{url}">{label} →</a></p><p class="meta">This is a free educational guide, not a current market call. Examples are hypothetical and do not promise an outcome.</p>'+offer()+'''</article><aside class="analysis-sidebar"><span class="premium-label">GO FURTHER</span><h2>The Sustainable Trader’s Kit</h2><p>The book, the Blueprint and a private community for putting a process into practice.</p><a href="/vip/#tickets">Compare the packages →</a><hr><h3>Prepare your session</h3><a href="/economic-calendar/">Economic calendar</a><a href="/tools/gold-position-size/">Gold position size</a><a href="/analysis/">All analysis guides</a></aside></div>'''
        page('/analysis/'+slug+'/',title,intro,body)
